package za.co.innaesim.backup.model;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

import lombok.Data;
import lombok.ToString;

/**
 * Everything loaded from the config file and schedules.d.
 *
 * Getters and setters are generated by Lombok, so they don't appear in this documentation.
 */
@Data
public class BackupSettings {
    private Map<String, JobConfig> jobs = new LinkedHashMap<>();
    private Map<String, DestinationConfig> destinations = new LinkedHashMap<>();
    @ToString.Exclude
    private String slackWebhookUrl;
    /** Which results go to Slack: "success" and/or "failure". */
    private Set<String> slackNotifyOn = Set.of("success", "failure");

    /** Creates empty settings that notify on both success and failure. */
    public BackupSettings() {}
}
